(function chart(){
 const claims=Object.fromEntries(D.claims.map(c=>[c.claim_id,c]));
 const kids={};for(const c of D.claims)for(const p of (c.parent_claim_ids||[]))if(claims[p])(kids[p]??=[]).push(c.claim_id);
 const roots=D.claims.filter(c=>!(c.parent_claim_ids||[]).some(p=>claims[p])).map(c=>c.claim_id);
 const W=250,H=46,GX=300,GY=58,depth={},row={};let next=0;
 const place=(id,d)=>{if(depth[id]!==undefined)return row[id];depth[id]=d;const ks=kids[id]||[];
  if(!ks.length){row[id]=next++;return row[id]}
  const ys=ks.map(k=>place(k,d+1));row[id]=ys.reduce((a,b)=>a+b,0)/ys.length;return row[id]};
 roots.forEach(r=>place(r,0));
