 let out='',w=0,h=0;const ns=(s)=>s;
 const box=id=>{const p=pos(id),c=claims[id],k=status(id),[f,s]=sty[k];w=Math.max(w,p.x+W+30);h=Math.max(h,p.y+H+30);
  const n=D.assessments.filter(a=>a.claim_id===id).length;
  return `<g><title>${esc(c.text)}\n[${esc(id)}] ${k}, ${n} assessments</title><rect x="${p.x}" y="${p.y}" width="${W}" height="${H}" rx="8" fill="${f}" stroke="${s}" stroke-width="1.6"${k==='never'?' stroke-dasharray="5 3"':''}/>
  <text x="${p.x+8}" y="${p.y+18}">${esc(cut(c.text,40))}</text><text class="sm" x="${p.x+8}" y="${p.y+35}">${esc(id)} · ${esc(String(c.kind).replaceAll('_',' '))}</text></g>`};
 let edges='';
 for(const c of D.claims)for(const p of (c.parent_claim_ids||[])){if(!claims[p])continue;const a=pos(c.claim_id),b=pos(p);
