  edges+=`<path d="M${gx+10},${gy} C${gx+45},${gy} ${t.x-40},${t.y+H/2} ${t.x},${t.y+H/2}" fill="none" stroke="#c17934" stroke-width="2" stroke-dasharray="5 3"/>`;
  gates+=`<g><title>${esc(l.relation)} · ${esc(l.modality)} · ${esc(l.basis)}</title><circle cx="${gx}" cy="${gy}" r="10" fill="#fff7e9" stroke="#c17934" stroke-width="1.6"/>
