325	function traceSet(id){
326	  const s = new Set([id]);
327	  const up = x => effectsOf(x).forEach(e => { if (!s.has(e)) { s.add(e); up(e); } });
328	  up(id);
329	  (byEffect[id]?.cause_ids || []).forEach(c => s.add(c));
330	  return s;
331	}
332	function render(){
333	  const tr = state.trace ? traceSet(state.sel) : null;
334	  const U = new Set([state.sel]); if (tr) { const up = x => effectsOf(x).forEach(e => { if (!U.has(e)) { U.add(e); up(e); } }); up(state.sel); }
335	  ORDER.forEach(id => {
336	    const n = N[id], b = boxEls[id];
337	    const off = !n.focal && !state.statusOn.has(n.epistemic_status);
338	    const srcHit = state.src && n.source_ids.includes(state.src);
339	    const dim = off || (tr && !tr.has(id)) || (state.src && !srcHit);
340	    b.classList.toggle("dim", !!dim);
341	    b.classList.toggle("sel", state.trace && id === state.sel);
342	    b.classList.toggle("srcmark", !!srcHit);
343	  });
344	  edgeEls.forEach(({c, g}) => {
345	    let on = true;
346	    if (tr) on = U.has(c.effect_id) && c.cause_ids.some(x => tr.has(x));
347	    if (state.src) on = on && (c.source_ids.includes(state.src));
348	    g.classList.toggle("dimE", !on);
349	  });
350	  renderPanel();
351	}
352	function nodeLink(id){ return `<button class="nl" data-go="${id}"><span class="mono">${id}</span><span>${esc(LABEL[id])}</span></button>`; }
353	function srcBtns(ids){ return `<div class="srcs">${ids.map(s => `<button class="srcbtn" data-src="${esc(s)}" aria-pressed="${state.src===s}" title="${esc(SRC[s]?.[0]||s)}">${esc(SRC_SHORT(s))}</button>`).join("")}</div>`; }
354	function renderPanel(){
355	  const id = state.sel, n = N[id], st = ST[n.epistemic_status], ct = CT[n.cause_type];
356	  const c = byEffect[id];
357	  const effs = effectsOf(id);
358	  let h = "";
359	  if (state.src) h += `<div class="srcfilter"><span>Showing nodes citing <b>${esc(SRC_SHORT(state.src))}</b>: ${esc(SRC[state.src]?.[0]||"")}</span><button data-clearsrc>Clear</button></div>`;
360	  h += `<div class="pid"><span>${id}${n.focal ? " · focal event" : ""}</span></div>`;
361	  h += `<h2>${esc(LABEL[id])}</h2><p class="stmt">${esc(n.statement)}</p>`;
362	  h += `<div class="tags"><span class="tag ${st[0]}">${st[1]}</span><span class="tag ${ct[0]}">${ct[2]}</span></div>`;
363	  h += `<div><h3>Evidence</h3>${srcBtns(n.source_ids)}</div>`;
364	  if (c) {
365	    h += `<div class="conn"><h3>Caused by</h3><div class="gh"><span class="gatepill">${c.combination}</span><span class="sup ${c.support_status}">${c.support_status}</span><span class="hint">${c.combination==="AND"?"all required together":c.combination==="OR"?"alternatives":"grouping unknown"}</span></div>
366	      <div class="nodelinks">${c.cause_ids.map(nodeLink).join("")}</div><p>${esc(c.mechanism)}</p>${srcBtns(c.source_ids)}</div>`;
367	  } else {
368	    h += `<div class="conn"><h3>Caused by</h3><p class="empty">Chart ends here. No further cause is supported by the packet${n.epistemic_status==="unresolved_premise"||n.epistemic_status==="proposed_mechanism"?"; this premise still needs confirming":""}.</p></div>`;
369	  }
370	  if (effs.length) {
371	    h += `<div class="conn"><h3>Contributes to</h3>${effs.map(e => { const ec = byEffect[e]; return `${nodeLink(e)}<div class="gh" style="padding-left:4px"><span class="gatepill">${ec.combination}</span><span class="sup ${ec.support_status}">${ec.support_status}</span></div>`; }).join("")}</div>`;
372	  }
373	  const qs = qsFor(id);
374	  if (qs.length) h += `<div class="conn"><h3>Open questions</h3><ol class="qlist">${qs.map(([q,i]) => `<li><button class="nl" data-q="${i}" style="padding:0"><span>${esc(q.question)}</span></button></li>`).join("")}</ol></div>`;
375	  const panel = document.getElementById("panel"); panel.innerHTML = h;
376	}
377	document.getElementById("panel").addEventListener("click", e => {
378	  const g = e.target.closest("[data-go]"); if (g) { select(g.dataset.go, true, true); return; }
379	  const s = e.target.closest("[data-src]"); if (s) { state.src = state.src === s.dataset.src ? null : s.dataset.src; render(); return; }
380	  if (e.target.closest("[data-clearsrc]")) { state.src = null; render(); return; }
381	  const q = e.target.closest("[data-q]"); if (q) { showTab("q"); const el = document.getElementById("q" + q.dataset.q); el?.scrollIntoView({behavior:"smooth", block:"center"}); el?.focus(); }
382	});
383	function select(id, trace, scroll){
384	  state.sel = id; state.trace = trace; render();
385	  if (scroll) {
386	    const vp = document.getElementById("viewport"), p = pos[id];
387	    vp.scrollTo({ left: Math.max(0, p.x * state.scale - vp.clientWidth / 3), top: Math.max(0, p.y * state.scale - vp.clientHeight / 2 + BH), behavior: "smooth" });
388	  }
389	}
390	function applyScale(){
391	  stage.style.transform = `scale(${state.scale})`;
392	  const sw = document.getElementById("stagewrap"); sw.style.width = W * state.scale + "px"; sw.style.height = H * state.scale + "px";
393	}
394	document.getElementById("zIn").onclick = () => { state.scale = Math.min(1.4, state.scale + 0.1); applyScale(); };
395	document.getElementById("zOut").onclick = () => { state.scale = Math.max(0.3, state.scale - 0.1); applyScale(); };
396	document.getElementById("zFit").onclick = () => { const vp = document.getElementById("viewport"); state.scale = Math.max(0.25, Math.min(1, (vp.clientWidth - 8) / W, (vp.clientHeight - 8) / H)); applyScale(); };
397	document.getElementById("zReset").onclick = () => { state.trace = false; state.src = null; render(); };
398	
399	// --- tabs
400	function showTab(t){
401	  document.querySelectorAll("nav.tabs button").forEach(b => b.setAttribute("aria-selected", b.dataset.tab === t));
402	  document.getElementById("view-board").hidden = t !== "board";
403	  document.getElementById("view-q").hidden = t !== "q";
404	  document.getElementById("view-ev").hidden = t !== "ev";
405	  try { localStorage.setItem("r3tab", t); } catch (e) {}
406	}
407	document.querySelectorAll("nav.tabs button").forEach(b => b.addEventListener("click", () => showTab(b.dataset.tab)));
408	
409	// --- questions
410	document.getElementById("qgrid").innerHTML = D.unresolved_conditions.map((q,i) => `
411	  <article class="qcard" id="q${i}" tabindex="-1">
412	    <span class="qn">Q${String(i+1).padStart(2,"0")}</span>
413	    <h4>${esc(q.question)}</h4>
414	    <p>${esc(q.why_unresolved)}</p>
415	    <div class="nodechips">${q.related_node_ids.map(id => `<button class="nodechip" data-go="${id}" title="${esc(LABEL[id])}">${id} · ${esc(LABEL[id])}</button>`).join("")}</div>
416	  </article>`).join("");
417	// --- evidence
418	const cites = s => ORDER.filter(id => N[id].source_ids.includes(s)).length;
419	const ecites = s => D.causal_connections.filter(c => c.source_ids.includes(s)).length;
420	document.getElementById("evtable").innerHTML = `<thead><tr><th>ID</th><th>Record</th><th>Limits noted in the record</th><th>Nodes</th><th>Links</th><th></th></tr></thead><tbody>` +
421	  Object.entries(SRC).map(([s,[t,l]]) => `<tr><td class="mono">${esc(SRC_SHORT(s))}</td><td>${esc(t)}</td><td class="lim">${esc(l)}</td><td class="num">${cites(s)}</td><td class="num">${ecites(s)}</td><td><button data-showsrc="${esc(s)}">Show on board</button></td></tr>`).join("") + `</tbody>`;
422	document.addEventListener("click", e => {
423	  const g = e.target.closest(".nodechip[data-go]"); if (g) { showTab("board"); select(g.dataset.go, true, true); }
424	  const s = e.target.closest("[data-showsrc]"); if (s) { state.src = s.dataset.showsrc; state.trace = false; showTab("board"); render(); }
425	});
426	
427	applyScale(); render();
428	try { const t = localStorage.getItem("r3tab"); if (t) showTab(t); } catch (e) {}
429	</script>
430	
431	</body></html>

