14	from typing import Any
15	
16	PAGE = r'''<!doctype html>
17	<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
18	<title>RCA Board View</title>
19	<style>
20	:root{--ink:#142135;--muted:#607188;--line:#dae3ec;--blue:#235bc0;--green:#16784c;--red:#bc3e56;--amber:#a76a1e}
21	*{box-sizing:border-box}body{margin:0;font:15px/1.45 system-ui,-apple-system,Segoe UI,Arial,sans-serif;color:var(--ink);background:#f4f7fa}
22	header{background:#10243d;color:#fff;padding:18px 28px;display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
23	header h1{margin:0;font-size:20px}header p{margin:4px 0 0;color:#cad9ee;font-size:13px}
