43	.legend i{display:inline-block;width:12px;height:12px;border-radius:3px;margin-right:5px;vertical-align:-2px;border:1.5px solid}
44	#chart text{font:12px system-ui,Arial,sans-serif;fill:#142135}#chart .sm{font-size:10.5px;fill:#607188}
45	@media(max-width:1000px){.grid{grid-template-columns:1fr}}
46	</style></head><body>
47	<header><div><h1>RCA board · final state of the run</h1><p id="case"></p></div><div class="flag" id="status"></div></header>
48	<div class="wrap">
49	<div class="note">Workflow output on synthetic fixtures. Candidate links are not conclusions, and no root cause has been decided here. A quote counts once however many times it was re-assessed.</div>
50	<div class="stats" id="stats"></div>
51	<section class="card"><h2>RCA chart</h2>
52	<div class="legend" id="legend"></div>
53	<div class="chart"><svg id="chart"></svg></div></section>
54	<div class="grid"><div>
55	<section class="card"><h2>Claims and the evidence found for them</h2><div id="claims"></div></section>
56	<section class="card"><h2>Candidate causal links (not confirmed)</h2><div id="links"></div></section>
57	</div><div>
58	<section class="card"><h2>Documents: registered vs ever assessed</h2><div id="materials"></div></section>
59	<section class="card"><h2>Requests for more evidence</h2><div id="requests"></div></section>
60	<section class="card"><h2>Open needs</h2><div id="needs"></div></section>
61	<section class="card"><h2>Jobs rejected during the run</h2><div id="failures"></div></section>
62	</div></div></div>
63	<script>
64	const D = __DATA__;
65	const $=id=>document.getElementById(id);
66	const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
67	const eff=a=>String(a.effect||'').split('.').pop().toLowerCase();
68	const st=v=>String(v||'').split('.').pop();
69	const badge=(t,c)=>`<span class="badge ${c||'n'}">${esc(String(t).replaceAll('_',' '))}</span>`;
70	const titleOf=Object.fromEntries(D.materials.map(m=>[m.material_id,m.title||m.material_id]));
71	$('case').textContent=`Case ${D.case_id}`;
72	$('status').textContent=D.status;
73	const assessedMats=new Set(D.assessments.map(a=>a.material_id));
74	const pairs=new Set(D.assessments.map(a=>a.claim_id+'|'+a.exact_text));
75	const counts=D.assessments.reduce((m,a)=>(m[eff(a)]=(m[eff(a)]||0)+1,m),{});
76	const stats=[[D.claims.length,'claims'],[D.links.length,'candidate causal links'],
77	 [D.materials.length,'documents registered'],[[...assessedMats].filter(x=>titleOf[x]).length,'documents ever assessed'],
78	 [D.assessments.length,'assessments (with repeats)'],[pairs.size,'distinct claim-sentence pairs'],
79	 [(counts.supports||0)+' / '+(counts.contradicts||0),'supports / contradicts'],[counts.neutral||0,'neutral'],
80	 [D.needs.filter(n=>st(n.state)==='open').length,'open needs']];
81	$('stats').innerHTML=stats.map(([v,l])=>`<div class="stat"><b>${esc(v)}</b><span>${esc(l)}</span></div>`).join('');
82	// RCA chart: the reported event on the right, sub-claims to its left, candidate causal links as gates
83	(function chart(){
84	 const claims=Object.fromEntries(D.claims.map(c=>[c.claim_id,c]));
85	 const kids={};for(const c of D.claims)for(const p of (c.parent_claim_ids||[]))if(claims[p])(kids[p]??=[]).push(c.claim_id);
86	 const roots=D.claims.filter(c=>!(c.parent_claim_ids||[]).some(p=>claims[p])).map(c=>c.claim_id);
87	 const W=250,H=46,GX=350,GY=58,depth={},row={};let next=0;
88	 const place=(id,d)=>{if(depth[id]!==undefined)return row[id];depth[id]=d;const ks=kids[id]||[];
89	  if(!ks.length){row[id]=next++;return row[id]}
90	  const ys=ks.map(k=>place(k,d+1));row[id]=ys.reduce((a,b)=>a+b,0)/ys.length;return row[id]};
91	 roots.forEach(r=>place(r,0));
92	 const maxD=Math.max(0,...Object.values(depth));
93	 const pos=id=>({x:20+(maxD-depth[id]+1)*GX,y:20+row[id]*GY});
94	 const status=id=>{const l=D.assessments.filter(a=>a.claim_id===id);if(!l.length)return 'never';
95	  const s=l.some(a=>eff(a)==='supports'),x=l.some(a=>eff(a)==='contradicts');
96	  return s&&x?'mixed':s?'supports':x?'contradicts':'neutral'};
97	 const sty={supports:['#e2f6eb','#16784c','supporting quote found'],contradicts:['#ffebee','#bc3e56','contradicting quote found'],
98	  mixed:['#fff1d8','#a76a1e','both supporting and contradicting'],neutral:['#eef2f6','#8696ab','looked at, nothing relevant found'],
99	  never:['#ffffff','#b9c6d6','never assessed']};
100	 $('legend').innerHTML=Object.values(sty).map(([f,s,t])=>`<span><i style="background:${f};border-color:${s}${t==='never assessed'?';border-style:dashed':''}"></i>${t}</span>`).join('')
101	  +'<span><i style="border-color:#c17934;background:#fff7e9;border-radius:50%"></i>candidate causal link (not confirmed)</span><span>grey line = sub-claim of</span>';
102	 const cut=(t,n)=>t.length>n?t.slice(0,n-1)+'…':t;
103	 let out='',w=0,h=0;const ns=(s)=>s;
104	 const box=id=>{const p=pos(id),c=claims[id],k=status(id),[f,s]=sty[k];w=Math.max(w,p.x+W+30);h=Math.max(h,p.y+H+30);
105	  const n=D.assessments.filter(a=>a.claim_id===id).length;
106	  return `<g><title>${esc(c.text)}\n[${esc(id)}] ${k}, ${n} assessments</title><rect x="${p.x}" y="${p.y}" width="${W}" height="${H}" rx="8" fill="${f}" stroke="${s}" stroke-width="1.6"${k==='never'?' stroke-dasharray="5 3"':''}/>
107	  <text x="${p.x+8}" y="${p.y+18}">${esc(cut(c.text,40))}</text><text class="sm" x="${p.x+8}" y="${p.y+35}">${esc(id)} · ${esc(String(c.kind).replaceAll('_',' '))}</text></g>`};
108	 let edges='';
109	 for(const c of D.claims)for(const p of (c.parent_claim_ids||[])){if(!claims[p])continue;const a=pos(c.claim_id),b=pos(p);
110	  const x1=a.x+W,y1=a.y+H/2,x2=b.x,y2=b.y+H/2,m=(x1+x2)/2;
111	  edges+=`<path d="M${x1},${y1} C${m},${y1} ${m},${y2} ${x2},${y2}" fill="none" stroke="#b9c6d6" stroke-width="1.3"/>`}
112	 let gates='';
113	 for(const l of D.links){const t=pos(l.target_claim_id),srcs=(l.source_claim_ids||[]).filter(s=>claims[s]);if(!srcs.length)continue;
114	  const gy=srcs.reduce((a,s)=>a+pos(s).y+H/2,0)/srcs.length,gx=t.x-(GX-W)/2;
115	  for(const s of srcs){const a=pos(s);edges+=`<path d="M${a.x+W},${a.y+H/2} L${gx-10},${gy}" fill="none" stroke="#c17934" stroke-width="1.6" stroke-dasharray="5 3"/>`}
116	  edges+=`<path d="M${gx+10},${gy} C${gx+30},${gy} ${t.x-30},${t.y+H/2} ${t.x},${t.y+H/2}" fill="none" stroke="#c17934" stroke-width="2" stroke-dasharray="5 3"/>`;
117	  gates+=`<g><title>${esc(l.relation)} · ${esc(l.modality)} · ${esc(l.basis)}</title><circle cx="${gx}" cy="${gy}" r="10" fill="#fff7e9" stroke="#c17934" stroke-width="1.6"/>
118	   <text x="${gx}" y="${gy+4}" text-anchor="middle" style="font-size:10px;font-weight:700">${esc(l.link_id)}</text>
119	   <text class="sm" x="${gx}" y="${gy-15}" text-anchor="middle">${esc(l.modality)}</text></g>`}
120	 const boxes=D.claims.filter(c=>depth[c.claim_id]!==undefined).map(c=>box(c.claim_id)).join('');
121	 const svg=$('chart');svg.setAttribute('width',w);svg.setAttribute('height',h);svg.setAttribute('viewBox',`0 0 ${w} ${h}`);
122	 svg.innerHTML=edges+gates+boxes;
123	})();
124	// claims
125	const byClaim={};
126	for(const a of D.assessments){(byClaim[a.claim_id]??=[]).push(a)}
127	$('claims').innerHTML=D.claims.map(c=>{
128	 const list=byClaim[c.claim_id]||[];
129	 const quotes=new Map();
130	 for(const a of list){const e=eff(a);if(e==='neutral')continue;
131	  const k=e+'|'+a.exact_text;const q=quotes.get(k)||{e,t:a.exact_text,m:a.material_id,n:0,why:a.rationale};q.n++;quotes.set(k,q)}
132	 const distinct=new Set(list.map(a=>a.exact_text)).size;
133	 const s=[...quotes.values()].filter(q=>q.e==='supports').length,x=[...quotes.values()].filter(q=>q.e==='contradicts').length;
134	 const body=[...quotes.values()].map(q=>`<div class="quote ${q.e}">${badge(q.e,q.e)} “${esc(q.t)}”<div class="sub">${esc(titleOf[q.m]||q.m)} · assessed ${q.n}×${q.why?' · '+esc(q.why):''}</div></div>`).join('');
135	 return `<div class="item"><span class="label">${esc(c.text)}</span>${badge(c.kind,'info')}<div class="id">${esc(c.claim_id)}</div>
136	 <div class="sub">${list.length?`${distinct} distinct sentence(s) looked at · ${s} supporting · ${x} contradicting`:'<span class="warn badge">never assessed</span>'}</div>
137	 ${body?`<details open><summary>Evidence found</summary>${body}</details>`:''}</div>`}).join('')||'<p class="empty">No claims</p>';
138	$('links').innerHTML=D.links.map(l=>`<div class="item"><span class="label">${esc((l.source_claim_ids||[]).join(' + '))} → ${esc(l.target_claim_id)}</span>${badge(st(l.status),'warn')}
139	 <div class="sub">${esc(l.relation)} · ${esc(l.modality)} · basis: ${esc(l.basis)}</div>${l.source_text?`<details><summary>Source text</summary><div class="quote">${esc(l.source_text)}</div></details>`:''}</div>`).join('')||'<p class="empty">None</p>';
140	$('materials').innerHTML=D.materials.map(m=>`<div class="item"><span class="label">${esc(m.title)}</span>${assessedMats.has(m.material_id)?badge('assessed','supports'):badge('never assessed','warn')}
141	 <div class="sub">${esc(m.source_kind)} · ${esc(m.lineage)}</div></div>`).join('');
142	$('requests').innerHTML=D.requests.map(r=>`<div class="item"><span class="label">${esc(r.wording)}</span>${badge(st(r.state),st(r.state)==='rejected'?'contradicts':'info')}
143	 <div class="sub">for ${esc((r.target_ids||[]).join(', '))}</div></div>`).join('')||'<p class="empty">None</p>';
