.nb .ev{font-weight:700;color:#142135}.nb .xp{border:1px solid #8aa0bb;border-radius:10px;padding:0 7px;background:#fff;font-weight:700;color:#235bc0}
.nb .xp:hover{background:#235bc0;color:#fff}
