.item.doc{cursor:pointer}.item.doc:hover{background:#f3f7fd}.item.doc.on{background:#fff1d8}
@media(max-width:1000px){.grid,.boardgrid{grid-template-columns:1fr}aside.panel{position:static;max-height:none}}

