import pypdf,json,html
from pypdf.generic import ContentStream
r=pypdf.PdfReader("/Users/dhwanilchauhan/Desktop/RCA Try 1/Email Attachments for [NAME]/01 - Original Supplied R3 RCA Chart.pdf")
pg=r.pages[2]; H=float(pg.mediabox.height); W=float(pg.mediabox.width)
cs=ContentStream(pg.get_contents(),r)
def mul(m,n): # m then n applied: result = m x n  (row-vector convention a b c d e f)
    a,b,c,d,e,f=m; A,B,C,D,E_,F=n
    return (a*A+b*C, a*B+b*D, c*A+d*C, c*B+d*D, e*A+f*C+E_, e*B+f*D+F)
def ap(m,x,y): a,b,c,d,e,f=m; return (a*x+c*y+e, b*x+d*y+f)
ctm=(1,0,0,1,0,0); stack=[]; fill='#000'; stroke='#000'; lw=1
texts=[]; paths=[]; cur=[]; tm=tlm=None; fsz=10; start=None
def col(ops):
    v=[float(x) for x in ops]
    if len(v)==1: v=v*3
    return '#%02x%02x%02x'%tuple(int(round(max(0,min(1,x))*255)) for x in v[:3])
for ops,op in cs.operations:
    op=op.decode() if isinstance(op,bytes) else op
    if op=='q': stack.append((ctm,fill,stroke,lw))
    elif op=='Q': ctm,fill,stroke,lw=stack.pop()
    elif op=='cm': ctm=mul(tuple(float(x) for x in ops),ctm)
    elif op in('rg','g'): fill=col(ops)
    elif op in('RG','G'): stroke=col(ops)
    elif op=='w': lw=float(ops[0])
    elif op=='BT': tlm=(1,0,0,1,0,0)
    elif op=='Tf': fsz=abs(float(ops[1]))
    elif op=='Td': tlm=mul((1,0,0,1,float(ops[0]),float(ops[1])),tlm)
    elif op in('Tj','TJ'):
        raw=ops[0]
        s=''
        if op=='Tj': s=raw.decode('latin1') if isinstance(raw,bytes) else str(raw)
        else: s=''.join((x.decode('latin1') if isinstance(x,bytes) else str(x)) for x in raw if not isinstance(x,(int,float)))
        m=mul(tlm,ctm); x,y=ap(m,0,0); sc=abs(m[0]) or 1
        texts.append(dict(x=x,y=H-y,size=fsz*sc,fill=fill,t=s))
    elif op=='m': cur=[('M',ap(ctm,float(ops[0]),float(ops[1])))]
    elif op=='l': cur.append(('L',ap(ctm,float(ops[0]),float(ops[1]))))
    elif op=='c':
        p=[ap(ctm,float(ops[i]),float(ops[i+1])) for i in (0,2,4)]; cur.append(('C',p))
    elif op=='re':
        x,y,w,h=[float(v) for v in ops]; q=[ap(ctm,x,y),ap(ctm,x+w,y),ap(ctm,x+w,y+h),ap(ctm,x,y+h)]
        cur=[('M',q[0]),('L',q[1]),('L',q[2]),('L',q[3]),('Z',None)]
    elif op in('S','s','f','F','B','b','f*','B*'):
        paths.append(dict(seg=cur,op=op,fill=fill,stroke=stroke,lw=lw*abs(ctm[0])));cur=[]
    elif op=='n': cur=[]
def d(seg):
    o=[]
    for k,p in seg:
        if k=='M': o.append(f'M{p[0]:.1f},{H-p[1]:.1f}')
        elif k=='L': o.append(f'L{p[0]:.1f},{H-p[1]:.1f}')
        elif k=='C': o.append('C'+' '.join(f'{x:.1f},{H-y:.1f}' for x,y in p))
        else: o.append('Z')
    return ''.join(o)
svg=[f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}" style="background:#fff">']
for p in paths:
    f=p['fill'] if p['op'] in('f','F','B','b','f*','B*') else 'none'
    s=p['stroke'] if p['op'] in('S','s','B','b','B*') else 'none'
    svg.append(f'<path d="{d(p["seg"])}" fill="{f}" stroke="{s}" stroke-width="{max(p["lw"],.6):.1f}"/>')
for t in texts:
    svg.append(f'<text x="{t["x"]:.1f}" y="{t["y"]:.1f}" font-size="{t["size"]:.1f}" fill="{t["fill"]}" font-family="Arial">{html.escape(t["t"])}</text>')
svg.append('</svg>')
open('outputs/ground_truth_chart_render.html','w').write('<!doctype html><title>Ground truth render</title><body style="margin:0">'+''.join(svg))
json.dump(texts,open('outputs/ground_truth_chart_texts.json','w'),indent=1)
print(len(paths),len(texts),W,H)
E

