  "node_evidence": {
    "G07 hydraulics shut off, valve bleeding back, fluid leaves cylinder": [
      {"doc": "E10", "quote": "11:10: common B hydraulic supply shut down and isolated for separately planned utility maintenance. The guide-box task is shown in progress on the same outage status sheet.", "relation": "supports", "note": "the shutdown event and its time; arrives misfiled, Day +4 covering note"},
      {"doc": "E11", "quote": "Local tag IV-RB3-17 feeds the RB-3 lifting circuit from common header B.", "relation": "supports", "note": "connects the B supply to the lifting circuit"}
    ],
    "G13 isolation valve has slow bleed through": [
      {"doc": "E08", "quote": "With the handle at closed and differential pressure applied from the cylinder-side port toward the supply-side port, fluid seepage was observed.", "relation": "supports", "note": "bench test three days after the event; no calibrated rate; no Day 0 condition"},
      {"doc": "E08", "quote": "The record contains no installed-state pressure trace for Day 0 and no dated record establishing when the observed internal condition developed.", "relation": "insufficient", "note": "limits E08"},
      {"doc": "E16", "quote": "The valve workshop found seepage with the isolation handle at closed.", "relation": "supports", "note": "NOT independent: derived from E08 (E16 says so); count once"},
      {"doc": "E03", "quote": "The local valve position is checked \"closed\" at 10:47. The copy does not contain a sealing test result.", "relation": "insufficient", "note": "handle position is not a sealing test; absence of a record is not a result"},
      {"doc": "E15", "quote": "I did not perform a valve sealing test.", "relation": "consistent_with", "note": "no test was done by this person"},
      {"doc": "E09", "quote": "No sensor channel measuring flow through IV-RB3-17 was configured in the exported historian set.", "relation": "insufficient", "note": "no Day 0 flow measurement exists in this archive"},
      {"doc": "E10", "quote": "This sheet does not record the pressure on the isolated cylinder side of that valve.", "relation": "insufficient", "note": "no pressure record"}
    ],
    "G01 yoke drifted but carrier beam did not": [
