def _active_searches_per_claim(self) -> dict[str, int]:
    counts: dict[str, int] = {}
    for item in self.lead.work.values():
        if item.role == Role.EVIDENCE_WORKER and item.state in {JobState.QUEUED, JobState.RUNNING}:
            for target in item.target_ids:
                counts[target] = counts.get(target, 0) + 1
    return counts

