for c in causes:
    label = label_for(truth, c.get("text", ""))
    if label is not None:
        claim_nodes[c.get("claim_id")] = {n["id"]: n["fit"] for n in label["nodes"]}
        match_source[label["source"]] += 1
    else:
        claim_nodes[c.get("claim_id")] = {nid: "word_match" for nid in node_text
